package com.digiaudit.grcpc.modules.masterdata.catalog.policy.application;
import com.digiaudit.grcpc.common.exception.*;import com.digiaudit.grcpc.modules.document.api.dto.*;import com.digiaudit.grcpc.modules.document.application.DocumentCommandService;import com.digiaudit.grcpc.modules.document.domain.DocumentLinkTargetType;import com.digiaudit.grcpc.modules.masterdata.catalog.policy.api.dto.CentralPolicyDtos;import com.digiaudit.grcpc.modules.masterdata.catalog.policy.domain.*;import com.digiaudit.grcpc.modules.masterdata.catalog.policy.domain.entity.*;import com.digiaudit.grcpc.modules.masterdata.catalog.policy.domain.repository.*;import com.digiaudit.grcpc.modules.masterdata.catalog.shared.application.CatalogCommandSupport;import com.digiaudit.grcpc.modules.masterdata.revision.application.*;import com.digiaudit.grcpc.modules.masterdata.revision.domain.*;import com.digiaudit.grcpc.modules.masterdata.shared.api.dto.*;import com.digiaudit.grcpc.modules.masterdata.shared.domain.*;import com.fasterxml.jackson.databind.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;
@Service public class CentralPolicyVersionCommandService{private final CentralPolicyVersionRepository repository;private final CentralPolicyRepository policies;private final MasterDataRevisionCoordinator revisions;private final MasterDataRevisionActorProvider actors;private final DocumentCommandService documents;private final CatalogCommandSupport support;private final ObjectMapper mapper;private final Clock clock;public CentralPolicyVersionCommandService(CentralPolicyVersionRepository r,CentralPolicyRepository p,MasterDataRevisionCoordinator rev,MasterDataRevisionActorProvider a,DocumentCommandService d,CatalogCommandSupport s,ObjectMapper m,@Qualifier("masterDataRevisionClock")Clock c){repository=r;policies=p;revisions=rev;actors=a;documents=d;support=s;mapper=m;clock=c;}
public MasterDataAggregateMutationResponse create(UUID policyId,CentralPolicyDtos.CreateVersion r){support.validateValidity(r.validFrom(),r.validTo());AtomicReference<List<DocumentCommandResponse>>docs=new AtomicReference<>(List.of());try{var result=revisions.execute(RevisionRequest.central("Create policy version for "+policyId,"Policy Version draft create",null),c->{var policy=policies.lockById(policyId).orElseThrow(()->new NotFoundException("PARENT_NOT_FOUND","error.masterdata.v2.parentNotFound","Policy not found",policyId));if(policy.getStatus()!=MasterDataLifecycleStatus.ACTIVE)throw new UnprocessableEntityException("INVALID_PARENT","error.masterdata.v2.invalidParent","Policy must be active");var locked=repository.lockAllByPolicyId(policyId);int number=locked.stream().mapToInt(CentralPolicyVersionEntity::getVersionNumber).max().orElse(0)+1;var prepared=documents.prepareAggregate(r.documents());var e=CentralPolicyVersionEntity.createDraft(UUID.randomUUID(),policyId,number,normalizeContent(r.content()),r.validFrom(),r.validTo(),actors.currentActorId(),Instant.now(clock));var saved=repository.saveAndFlush(e);docs.set(documents.finalizePreparedAggregate(prepared,DocumentLinkTargetType.CENTRAL_POLICY_VERSION,saved.getId(),"CENTRAL_POLICY_CREATE"));return completed(c,saved,RevisionOperationType.CREATE,null,null);});return support.aggregateResponse(result,docs.get());}catch(DataIntegrityViolationException e){throw new ConflictException("DUPLICATE_BUSINESS_KEY","error.masterdata.v2.duplicateBusinessKey","Policy version number allocation conflicted",policyId);}}
public MasterDataAggregateMutationResponse update(UUID id,CentralPolicyDtos.UpdateVersion r){long expected=support.requireVersion(r.version());support.validateValidity(r.validFrom(),r.validTo());AtomicReference<List<DocumentCommandResponse>>docs=new AtomicReference<>(List.of());var result=revisions.execute(RevisionRequest.central("Update policy version "+id,"Policy Version draft update",null),c->{var prepared=documents.prepareAggregate(r.documents());var e=lock(id);assertVersion(e,expected);requireDraft(e);String content=normalizeContent(r.content());if(Objects.equals(e.getContent(),content)&&Objects.equals(e.getValidFrom(),r.validFrom())&&Objects.equals(e.getValidTo(),r.validTo())&&empty(r.documents()))throw new UnprocessableEntityException("NO_CHANGE","error.masterdata.v2.noChange","The command contains no change");JsonNode before=snapshot(e);e.updateDraft(content,r.validFrom(),r.validTo(),actors.currentActorId(),Instant.now(clock));var saved=repository.saveAndFlush(e);docs.set(documents.finalizePreparedAggregate(prepared,DocumentLinkTargetType.CENTRAL_POLICY_VERSION,id,"CENTRAL_POLICY_UPDATE"));return completed(c,saved,RevisionOperationType.UPDATE,expected,before);});return support.aggregateResponse(result,docs.get());}
public MasterDataRevisionMutationResponse publish(UUID id,Long version){long expected=support.requireVersion(version);var result=revisions.execute(RevisionRequest.central("Publish policy version "+id,"Publish draft and supersede previous publication",null),c->{var candidate=repository.findById(id).orElseThrow(()->notFound(id));policies.lockById(candidate.getPolicyId()).orElseThrow(()->new NotFoundException("PARENT_NOT_FOUND","error.masterdata.v2.parentNotFound","Policy not found",candidate.getPolicyId()));var locked=repository.lockAllByPolicyId(candidate.getPolicyId());var target=locked.stream().filter(v->v.getId().equals(id)).findFirst().orElseThrow(()->notFound(id));assertVersion(target,expected);requireDraft(target);if(target.getContent()==null||target.getContent().isBlank())throw new UnprocessableEntityException("INVALID_POLICY_PUBLICATION","error.masterdata.v2.invalidPolicyPublication","Policy content is required before publication",id);List<RevisionContentResult>contents=new ArrayList<>();UUID actor=actors.currentActorId();Instant now=Instant.now(clock);for(var current:locked){if(current.getVersionStatus()==PolicyVersionStatus.PUBLISHED){long oldVersion=current.getVersion();JsonNode before=snapshot(current);current.supersede(actor,now);repository.save(current);repository.flush();contents.add(content(current,RevisionOperationType.UPDATE,oldVersion,before));}}JsonNode before=snapshot(target);target.publish(actor,now);var saved=repository.saveAndFlush(target);contents.add(content(saved,RevisionOperationType.UPDATE,expected,before));return RevisionOperationResult.completed(c,new MasterDataMutationResult(saved.getId(),c.revisionId(),saved.getVersion()),contents);});return MasterDataRevisionMutationResponse.from(result.primaryResult());}
public MasterDataRevisionMutationResponse delete(UUID id,Long version){return draftLifecycle(id,version,false);}public MasterDataRevisionMutationResponse restore(UUID id,Long version){return draftLifecycle(id,version,true);}private MasterDataRevisionMutationResponse draftLifecycle(UUID id,Long version,boolean restore){long expected=support.requireVersion(version);var op=restore?RevisionOperationType.RESTORE:RevisionOperationType.DELETE;var result=revisions.execute(RevisionRequest.central(op+" policy version "+id,"Policy Version draft lifecycle",null),c->{var e=lock(id);assertVersion(e,expected);if(restore){if(e.getVersionStatus()!=PolicyVersionStatus.DRAFT||e.getStatus()!=MasterDataLifecycleStatus.DELETED)throw immutable();}else requireDraft(e);JsonNode before=snapshot(e);if(restore)e.restoreDraft(actors.currentActorId(),Instant.now(clock));else e.deleteDraft(actors.currentActorId(),Instant.now(clock));return completed(c,repository.saveAndFlush(e),op,expected,before);});return MasterDataRevisionMutationResponse.from(result.primaryResult());}
private String normalizeContent(String content){return content==null||content.isBlank()?null:content.trim();}private CentralPolicyVersionEntity lock(UUID id){return repository.lockById(id).orElseThrow(()->notFound(id));}private void assertVersion(CentralPolicyVersionEntity e,long v){if(e.getVersion()!=v)throw new ConflictException("VERSION_CONFLICT","error.masterdata.v2.versionConflict","The policy version has changed",e.getId());}private void requireDraft(CentralPolicyVersionEntity e){if(e.getVersionStatus()!=PolicyVersionStatus.DRAFT||e.getStatus()==MasterDataLifecycleStatus.DELETED)throw immutable();}private UnprocessableEntityException immutable(){return new UnprocessableEntityException("IMMUTABLE_POLICY_VERSION","error.masterdata.v2.immutablePolicyVersion","Published and superseded policy versions are immutable");}private NotFoundException notFound(UUID id){return new NotFoundException("MASTER_DATA_NOT_FOUND","error.masterdata.v2.notFound","Policy Version not found",id);}private JsonNode snapshot(CentralPolicyVersionEntity e){Map<String,Object>m=new LinkedHashMap<>();m.put("id",e.getId());m.put("policyId",e.getPolicyId());m.put("versionNumber",e.getVersionNumber());m.put("content",e.getContent());m.put("versionStatus",e.getVersionStatus());m.put("publishedAt",e.getPublishedAt());m.put("publishedBy",e.getPublishedBy());m.put("status",e.getStatus().wireValue());m.put("validFrom",e.getValidFrom());m.put("validTo",e.getValidTo());m.put("version",e.getVersion());return mapper.valueToTree(m);}private RevisionContentResult content(CentralPolicyVersionEntity e,RevisionOperationType op,Long expected,JsonNode before){return RevisionContentResult.completed(RevisionEntityType.CENTRAL_POLICY_VERSION,e.getId(),op,expected,before,snapshot(e),e.getVersion(),mapper.valueToTree(Map.of("validated",true)));}private RevisionOperationResult completed(RevisionExecutionContext c,CentralPolicyVersionEntity e,RevisionOperationType op,Long expected,JsonNode before){return RevisionOperationResult.completed(c,new MasterDataMutationResult(e.getId(),c.revisionId(),e.getVersion()),List.of(content(e,op,expected,before)));}private boolean empty(DocumentAggregateBatchRequest r){return r==null||(r.newDocuments().isEmpty()&&r.newVersions().isEmpty()&&r.metadataUpdates().isEmpty());}}
